def calcular_frete(peso: float, regiao: str, servico: str = 'padrao') -> float:
    """Calcula o valor do frete com base em peso, região e tipo de serviço."""
    taxa_por_regiao = {
        'norte': 4.0,
        'sul': 5.5,
        'nordeste': 6.5,
        'sudeste': 7.0,
        'centro-oeste': 6.0,
    }
    acrescimo_por_servico = {
        'padrao': 0.0,
        'expresso': 12.0,
        'fragil': 18.0,
    }
    taxa = taxa_por_regiao.get(regiao.lower(), 5.0)
    acrescimo = acrescimo_por_servico.get(servico.lower(), 0.0)
    return round(peso * taxa + acrescimo, 2)
